state.labFormat=state.labFormat===40?40:20;save();let labRoof=false,labAngle=-.5;
const labModels={20:{length:6.058,width:2.438,height:2.591,works:18000,kitchen:18000,lab:36000,total:54000},40:{length:12.192,width:2.438,height:2.591,works:25000,kitchen:18000,lab:43000,total:61000}};
const labZones=[['Réception & stockage','#c1d1b2','Contrôle des livraisons, identification des lots et stockage adapté aux denrées.'],['Lavage & préparation brute','#c4d8d4','Traitement des matières premières. Organisation pour limiter les contaminations croisées.'],['Préparation & cuisson','#e4d3ad','Plans de travail et équipements de cuisine. Gestes et températures à définir dans le plan de maîtrise sanitaire.'],['Conditionnement & conservation','#d2dcb8','Protection des préparations, conservation adaptée et traçabilité des lots.'],['Sortie vers les casiers','#d9bf99','Produits prêts au retrait, informations allergènes et maîtrise de la chaîne du froid selon les denrées.']];
function labChoice(){return `<div class="labselector" aria-label="Format du laboratoire"><button aria-pressed="${state.labFormat===20}" onclick="chooseLab(20)">Container 20 pieds</button><button aria-pressed="${state.labFormat===40}" onclick="chooseLab(40)">Container 40 pieds</button><small>Format actif partagé entre les vues 3D et la présentation.</small></div>`}
function chooseLab(n){state.labFormat=n===40?40:20;save();render();if($('#deck').open)renderSlide();toast('Laboratoire '+state.labFormat+' pieds : vues et budgets de présentation mis à jour.')}
function labDim(){let m=labModels[state.labFormat];return `${m.length.toFixed(2).replace('.',',')} × 2,44 × 2,59 m`}
function labBudget(){let m=labModels[state.labFormat];return `<div class="labfacts"><div><small>Container standard · dimensions extérieures indicatives</small><b>${state.labFormat} pieds</b><p>${labDim()}<br>Surface intérieure utile réduite après isolation et aménagement.</p></div><div><small>Poste principal · laboratoire aménagé et équipé</small><b>${money(m.lab)} HT</b><p>Aménagement ${money(m.works)} + cuisine ${money(m.kitchen)}.<br>Estimations du document fourni.</p></div><div><small>Besoin initial du projet</small><b>${money(m.total)} HT</b><p>Laboratoire + 12 000 € de casiers + 1 000 € d’encaissement + 5 000 € de trésorerie et communication.</p></div></div>`}
function labComparison(){return `<table class="labtable"><thead><tr><th>Prévisionnel fourni</th><th>20 pieds</th><th>40 pieds</th></tr></thead><tbody><tr><td>Aménagement du container</td><td>18 000 € HT</td><td>25 000 € HT</td></tr><tr><td>Équipements de cuisine</td><td>18 000 € HT</td><td>18 000 € HT</td></tr><tr class="totalrow"><td>Poste principal : laboratoire</td><td>36 000 € HT</td><td>43 000 € HT</td></tr><tr><td>Casiers + encaissement</td><td>13 000 € HT</td><td>13 000 € HT</td></tr><tr><td>Trésorerie et communication</td><td>5 000 €</td><td>5 000 €</td></tr><tr class="totalrow"><td>Besoin initial<small>Totaux exprimés HT dans le document. Ventilation de trésorerie à confirmer.</small></td><td>54 000 €</td><td>61 000 €</td></tr></tbody></table><p class="lab-source-note">Hypothèses de la simulation « Container de transformation anti gaspi prévisionnel 2027 ». Devis, transport, raccordements, autorisations, financement et exhaustivité des coûts à vérifier. Le changement de format ne modifie pas automatiquement les prévisions de ventes.</p>`}
function labSVG(format=state.labFormat){const m=labModels[format],L=m.length*10,W=24.38,H=25.91;let faces=[],a=labAngle,scale=3.9;function p(x,y,z){let u=x*Math.cos(a)-y*Math.sin(a),v=x*Math.sin(a)+y*Math.cos(a);return [400+u*scale,230+(v*.56-z*.83)*scale,v*.83+z*.56]};function poly(v,c,zone=''){let q=v.map(v=>p(...v));faces.push({q,c,zone,d:q.reduce((s,v)=>s+v[2],0)/q.length+(v.every(v=>v[2]<=.6)?-10000:0)})};function box(x,y,z,dx,dy,dz,c){let A=[x,y,z],B=[x+dx,y,z],C=[x+dx,y+dy,z],D=[x,y+dy,z],E=[x,y,z+dz],F=[x+dx,y,z+dz],G=[x+dx,y+dy,z+dz],J=[x,y+dy,z+dz];poly([A,B,F,E],c);poly([B,C,G,F],c);poly([C,D,J,G],c);poly([D,A,E,J],c);poly([E,F,G,J],c)}
const x=-L/2,y=-W/2;box(x-2,y-2,-2,L+4,W+4,2,'#9cac83');for(let i=0;i<5;i++)poly([[x+i*L/5,y,.4],[x+(i+1)*L/5,y,.4],[x+(i+1)*L/5,y+W,.4],[x+i*L/5,y+W,.4]],labZones[i][1]);box(x,y,0,L,.8,H,'#78916e');box(x,y,0,.8,W,H,'#91a185');box(x+L-.8,y,0,.8,W,labRoof?H:3,'#91a185');box(x,y+W-.8,0,L,.8,labRoof?H:2,'#9dae90');
for(let i=0;i<5;i++){let xx=x+2+i*L/5,ww=L/5-4;box(xx,y+2,0,ww,6,8,'#a8b9b1');box(xx,y+2,8,ww,6,.8,'#d5dfd7');if(i===0)box(xx+1,y+3,9,Math.max(2,ww-2),4,10,'#b9ccbc');if(i===1){box(xx+1,y+3,9,Math.max(2,ww-2),3,.4,'#6f989d')}if(i===2){for(let k=0;k<2;k++)box(xx+1+k*Math.max(2,(ww-3)/2),y+3,9,Math.max(1.5,(ww-3)/2),3,.5,'#4f605b');box(xx,y+1,H-5,ww,7,2,'#c0cbc2')}if(i===3)box(xx+1,y+3,9,Math.max(2,ww-2),4,3,'#ded5bc');if(i===4)box(xx+1,y+3,9,Math.max(2,ww-2),4,3,'#a0b488')}
// rangée complémentaire : équipements conceptuels, sans cote de circulation validée
box(x+1.5,y+W-6.5,0,4,4,8,'#b9cbc3');box(x+2,y+W-6,8,3,3,.5,'#789d9d');box(x+L*.25,y+W-7,0,L*.18,5,8,'#bac9bd');box(x+L*.62,y+W-7,0,L*.18,5,8,'#bac9bd');if(labRoof)box(x-1,y-1,H,L+2,W+2,1.5,'#6a8267');faces.sort((a,b)=>a.d-b.d);let polys=faces.map(f=>`<polygon points="${f.q.map(v=>v.slice(0,2).map(n=>n.toFixed(1)).join(',')).join(' ')}" fill="${f.c}" stroke="#5e775b22" stroke-width=".6"/>`).join('');let lineA=p(x,y+W+8,0),lineB=p(x+L,y+W+8,0);let zones=Array.from({length:5},(_,i)=>{const q=p(x+(i+.5)*L/5,0,labRoof?H+5:13);return `<g><circle cx="${q[0]}" cy="${q[1]}" r="10" fill="#fffef0" stroke="#899c6e"/><text x="${q[0]}" y="${q[1]+4}" text-anchor="middle" fill="#47643f" font-size="11" font-family="sans-serif">${i+1}</text></g>`}).join('');return `<svg viewBox="0 0 800 360" role="img" aria-label="Laboratoire en container de ${format} pieds, ${labRoof?'vue extérieure':'vue en coupe'}, cinq zones fonctionnelles illustratives"><ellipse cx="400" cy="250" rx="${L*2.2}" ry="45" fill="#7d956f18"/>${polys}${zones}<line x1="${lineA[0]}" y1="${lineA[1]}" x2="${lineB[0]}" y2="${lineB[1]}" stroke="#8b9c73"/><text x="${(lineA[0]+lineB[0])/2}" y="${(lineA[1]+lineB[1])/2+22}" text-anchor="middle" fill="#6c8156" font-family="sans-serif" font-size="12">${m.length.toFixed(2).replace('.',',')} m · ${format} pieds</text><text x="400" y="338" text-anchor="middle" fill="#879675" font-size="11" font-family="sans-serif">Largeur extérieure : environ 2,44 m · Plan conceptuel non validé</text></svg>`}
function labVisual(){return `<div class="labviewport"><span class="labviewlabel">LABORATOIRE ${state.labFormat} PIEDS · ${labRoof?'VUE EXTÉRIEURE':'VUE EN COUPE'}</span>${labSVG()}</div><div class="labtoolbar"><button onclick="labAngle-=.25;refreshLabVisual()" aria-label="Tourner le laboratoire à gauche">↶ Tourner</button><button onclick="labAngle+=.25;refreshLabVisual()" aria-label="Tourner le laboratoire à droite">Tourner ↷</button><button aria-pressed="${labRoof}" onclick="labRoof=!labRoof;refreshLabVisual()">${labRoof?'Retirer le toit':'Afficher le toit'}</button></div>`}function refreshLabVisual(){document.querySelectorAll('.labvisualhost').forEach(e=>e.innerHTML=labVisual())}
function labPlanView(){return heading('Le laboratoire : 20 ou 40 pieds.','Deux variantes 3D, un parcours de transformation et un budget comparatif.',`<button class="btn light" onclick="openPresentation()">▷ Présenter le projet</button>`)+labChoice()+`<div class="labvisualhost">${labVisual()}</div>`+labBudget()+`<div class="twocol"><section class="panel"><h2>Le parcours des produits</h2><p class="smallnote">Repères de la vue en coupe. Zones fonctionnelles indicatives, pas un cloisonnement ni un plan d’exécution. Accès, circulations, sanitaires et ventilation restent à dimensionner.</p>${labZones.map((z,i)=>`<div class="labzone"><span style="--zone:${z[1]}">${i+1}</span><div><h3>${z[0]}</h3><p>${z[2]}</p></div></div>`).join('')}<div class="notice">Version 20 pieds : espace plus compact, organisation dans le temps et nettoyage entre opérations à étudier. Version 40 pieds : davantage de longueur pour organiser les postes. Aucune capacité de production n’est validée par la maquette.</div></section><section class="panel"><div class="eyebrow">POSTE PRINCIPAL DU PROJET</div><h2 style="font-size:25px;margin:18px 0">Transformer un container<br>en laboratoire alimentaire.</h2><p class="sub">Le projet prévoit un aménagement destiné à satisfaire les exigences d’hygiène et des procédures fondées sur les principes HACCP dans un plan de maîtrise sanitaire.</p><span class="labstatus">Objectif de conception · conformité non attestée</span><div class="featureline"><span>01</span><div><b>Aménagement et équipements</b><p>Surfaces nettoyables, plans de travail adaptés, lave-mains, eau potable, évacuation, ventilation et stockage à dimensionner.</p></div></div><div class="featureline"><span>02</span><div><b>Flux à organiser</b><p>Limiter les contaminations croisées, organiser les opérations et le nettoyage. La marche en avant peut s’organiser dans l’espace ou dans le temps selon l’activité.</p></div></div><div class="featureline"><span>03</span><div><b>Validation avant exploitation</b><p>Confirmer le plan réel, les procédures et les formalités applicables avec les professionnels compétents et le service de contrôle du lieu d’implantation.</p></div></div><div class="lablinks"><a href="https://agriculture.gouv.fr/la-reglementation-sur-lhygiene-des-aliments" target="_blank" rel="noopener">Source : ministère de l’Agriculture · hygiène et principes HACCP ↗</a><a href="https://agriculture.gouv.fr/telecharger/79464" target="_blank" rel="noopener">Guide de bonnes pratiques · organisation des locaux ↗</a><a href="https://www.fesco.com/en/assets/containers/" target="_blank" rel="noopener">Dimensions indicatives : flotte de containers FESCO ↗</a></div></section></div><section class="panel"><h2>Deux formats, deux investissements</h2>${labComparison()}</section>`}
routes.splice(routes.findIndex(r=>r[0]==='antigaspi')+1,0,['labo3d','▱','Labo 20 / 40 pieds']);views.labo3d=labPlanView;
const originalCityDetail=cityDetailHTML;cityDetailHTML=function(){if(citySelected!=='labo')return originalCityDetail();let m=labModels[state.labFormat];return `<div class="eyebrow">LABORATOIRE ${state.labFormat} PIEDS</div><div class="place-icon">▤</div><h2>Le laboratoire anti-gaspi</h2><p>Container maritime de ${state.labFormat} pieds, aménagé pour la transformation alimentaire. Poste principal du prévisionnel.</p>${labChoice()}<div class="place-stat"><div><b>${money(m.lab)}</b>laboratoire · HT</div><div><b>${money(m.total)}</b>besoin initial · HT</div></div><button class="btn" onclick="location.hash='#labo3d'">Voir le plan 3D & HACCP ↗</button><p class="citydetailinfo">Objectif : aménagement et procédures fondés sur les principes HACCP. Conformité et plan d’exécution à faire valider.</p>`};
const baseCityView=views.ville;views.ville=function(){return baseCityView().replace('<div class="citylayout">',`<div class="labminiintro"><h3>Laboratoire anti-gaspi · deux versions intégrées au village</h3>${labChoice()}<p>Le format choisi modifie le volume du laboratoire en 3D. ${state.labFormat} pieds · ${labDim()} · poste principal : ${money(labModels[state.labFormat].lab)} HT.</p><a class="textlink" href="#labo3d">Voir l’intérieur, les postes de travail et le budget ↗</a></div><div class="citylayout">`)};
const residenceV3=residence3d;residence3d=function(){const result=residenceV3();return result.replace('class="object3d second"',`class="object3d second" style="--lablength:${labModels[state.labFormat].length*10}px;--lablabel:'LABO ${state.labFormat} PIEDS'"`)+`<div class="labminiintro"><h3>Laboratoire ${state.labFormat} pieds</h3>${labChoice()}<p>${labDim()} · aménagement et cuisine : ${money(labModels[state.labFormat].lab)} HT. Objectif HACCP à valider.</p><a class="textlink" href="#labo3d">Voir la coupe intérieure ↗</a></div>`};
const antigaspiV3=views.antigaspi;views.antigaspi=function(){let html=antigaspiV3();const start=html.indexOf('<div class="hero">'),end=html.indexOf('<div class="stats">');if(start>=0&&end>=0)html=html.slice(0,start)+`<section class="panel"><div class="eyebrow">LE POSTE PRINCIPAL : LE LABORATOIRE ALIMENTAIRE</div><h2 style="font-size:27px;margin:18px 0">Container maritime de 20 ou 40 pieds.</h2><p class="sub">Aménagement prévu selon les exigences d’hygiène et les principes HACCP. Validation technique et sanitaire à obtenir.</p>${labChoice()}<div class="labvisualhost">${labVisual()}</div>${labBudget()}<a class="btn light" href="#labo3d">Plan intérieur & comparaison des budgets ↗</a></section>`+html.slice(end);return html};
slides.splice(4,0,{k:'LE LABORATOIRE 20 / 40 PIEDS',title:'20 ou 40 pieds.<br>Le laboratoire au cœur du projet.',text:'La transformation du container maritime en laboratoire alimentaire constitue le poste principal du prévisionnel fourni. Les deux versions sont intégrées aux vues 3D.',cards:[['20 pieds · 36 000 € HT','18 000 € d’aménagement et 18 000 € de cuisine. Besoin initial du projet : 54 000 €.'],['40 pieds · 43 000 € HT','25 000 € d’aménagement et 18 000 € de cuisine. Besoin initial du projet : 61 000 €.'],['Un budget à confirmer','Casiers, encaissement et trésorerie inclus dans les besoins initiaux. Devis et exhaustivité des coûts à vérifier.']]},{k:'CONCEPTION ET HACCP',title:'Un laboratoire conçu<br>pour l’hygiène alimentaire.',text:'Objectif du projet : locaux et équipements adaptés, procédures fondées sur les principes HACCP et plan de maîtrise sanitaire. La maquette ne certifie pas la conformité.',cards:[['Organiser les flux','Réception, préparation, cuisson, conditionnement et sortie vers les casiers.'],['Prévenir les contaminations','Organisation dans l’espace ou dans le temps, nettoyage, eau potable et conservation adaptée.'],['Faire valider le plan réel','Implantation, équipements, procédures et formalités à confirmer avant exploitation.']]});slides.forEach((s,i)=>s.k=String(i+1).padStart(2,'0')+' · '+s.k.replace(/^\d+ · /,''));
const slideV3=renderSlide;renderSlide=function(){slideV3();const s=slides[slideIndex];if(s.k.includes('LE LABORATOIRE 20'))$('#slide .over').insertAdjacentHTML('beforeend',`<div class="labslidesummary">Version 3D active : ${state.labFormat} pieds · ${labDim()} · <a href="#labo3d" onclick="document.getElementById('deck').close()" style="text-decoration:underline">ouvrir le plan en coupe ↗</a></div>`)};
const resetV3=resetDemo;resetDemo=function(){resetV3();state.labFormat=20;save();render()};render();

const slideWithLabLink=renderSlide;renderSlide=function(){slideWithLabLink();if(slides[slideIndex].k.includes('LE LABORATOIRE 20')){const host=$('#slide');host.classList.add('labcomparisonslide');host.querySelector('.over').innerHTML=`<div class="eyebrow">${slides[slideIndex].k}</div><h2>Deux formats. Le même objectif.</h2><p>Le laboratoire alimentaire constitue le poste principal du prévisionnel. Les vues 3D ci-dessous utilisent la même échelle.</p><div class="labslidegrid">${[20,40].map(n=>`<figure><div class="labviewport">${labSVG(n)}</div><figcaption><b>${n} pieds · ${money(labModels[n].lab)} HT</b><span>Aménagement + cuisine · besoin initial du projet : ${money(labModels[n].total)}</span></figcaption></figure>`).join('')}</div><p class="labslidesummary">Objectif : aménagement selon les exigences d’hygiène et procédures fondées sur les principes HACCP. Plan conceptuel, conformité à valider.</p><a class="btn light" href="#labo3d" onclick="document.getElementById('deck').close()">Explorer le plan intérieur ↗</a>`}else $('#slide').classList.remove('labcomparisonslide')};
